#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b) {
    return a < b ? a : b;
}
int mx(int a, int b) {
    return a > b ? a : b;
}
int read(void) {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a) {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x) {
    printf("%d ", x);
}
void emitstr(int* a, int n) {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void) {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int cols = 0, i = 0, j = 0, rows = 0, x = 0;
    // 先读行列数，随后按行读取当前格值，不需要保存整张状态表。
    rows = read();
    cols = read();
    for (i = 0; i < rows; i += 1) {
        for (j = 0; j < cols; j += 1) {
            x = read();
            // 起点单独初始化；第一行和第一列只能来自唯一方向。
            if ((i == 0) && (j == 0)) {
                a[j] = x;
            }
            else {
                if (i == 0) {
                    a[j] = (a[(j - 1)] + x);
                }
                else {
                    if (j == 0) {
                        a[j] = (a[j] + x);
                    }
                    else {
                        // 更新前 a[j] 是上方状态，a[j-1] 已是本行左方状态。
                        a[j] = (mn(a[j], a[(j - 1)]) + x);
                    }
                }
            }
        }
    }
    // 最后一列的状态在处理完最后一行后就是右下角答案。
    emit(a[(cols - 1)]);
    return 0;
}

