import sys

_tokens = iter(sys.stdin.read().split())


def read():
    return int(next(_tokens))


def readstr(a):
    s = next(_tokens)
    if s == "-":
        return 0
    for i, c in enumerate(s):
        a[i] = ord(c)
    return len(s)


def emit(x):
    print(x, end=" ")


def emitstr(a, n):
    print("".join(chr(x) for x in a[:n]) if n else "-", end=" ")


def mn(a, b):
    return min(a, b)


def mx(a, b):
    return max(a, b)


a = [0] * 20000
b = [0] * 20000
d = [0] * 20000
e = [0] * 20000
cols = i = j = rows = x = 0
# 按行读网格，a 只需保存一行的最小路径和。
rows = read()
cols = read()
for i in range(rows):
    for j in range(cols):
        x = read()
        # 起点必须计入自身权值；边界只能从一个方向到达。
        if (i == 0) and (j == 0):
            a[j] = x
        else:
            if i == 0:
                a[j] = a[(j - 1)] + x
            else:
                if j == 0:
                    a[j] = a[j] + x
                else:
                    # a[j] 仍是上方，a[j-1] 已经是本行左侧，取较小来源加本格。
                    a[j] = mn(a[j], a[(j - 1)]) + x
# 右下角对应最后一行更新完的最后一列状态。
emit(a[(cols - 1)])

